describe('Admin Recipe Comments Moderation - Comments List', () => {
  const mockComments = [
    {
      id: 'c-1',
      recipe_id: '101',
      parent_id: null,
      author: 'FoodieSam',
      email: 'foodie@example.com',
      content: 'Loved this recipe! Can I use almond milk instead of dairy milk?',
      is_admin: false,
      status: 'approved',
      created_at: '2026-11-18T09:00:00.000Z',
      is_new: true,
    },
    {
      id: 'r-1',
      recipe_id: '101',
      parent_id: 'c-1',
      author: 'Delisha Marie',
      email: 'delisha@example.com',
      content: 'Yes, almond milk works great in this dish!',
      is_admin: true,
      status: 'approved',
      created_at: '2026-11-18T10:00:00.000Z',
      is_new: false,
    },
  ];

  beforeEach(() => {
    // Authenticate as member with tenant
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'delisha',
          email: 'delisha@example.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'member',
        status: 'active',
        tenant: {
          id: 't-1',
          name: "Delisha's Kitchen",
          slug: 'delisha-kitchen',
        },
        isImpersonating: false,
      },
    }).as('getMemberSession');
  });

  it('visit recipe comments page with comments → renders header, comment card with NEW badge, and existing replies', () => {
    cy.intercept('GET', '**/api/recipes/101/comments', {
      statusCode: 200,
      body: { comments: mockComments },
    }).as('getComments');

    cy.visit('/recipes/101/comments');
    cy.wait('@getComments');

    // Page Header
    cy.contains('h1', 'Review Comments').should('be.visible');

    // Top-level comment
    cy.contains('FoodieSam').should('be.visible');
    cy.contains('mat-chip', 'NEW').should('be.visible');
    cy.contains('Loved this recipe! Can I use almond milk instead of dairy milk?').should(
      'be.visible',
    );

    // Existing reply
    cy.contains('Delisha Marie').should('be.visible');
    cy.contains('Yes, almond milk works great in this dish!').should('be.visible');

    // Action buttons
    cy.contains('button', 'Reply').should('be.visible');
    cy.contains('button', 'Skip').should('be.visible');
  });

  it('visit recipe comments page with no new comments → displays empty state message', () => {
    cy.intercept('GET', '**/api/recipes/101/comments', {
      statusCode: 200,
      body: { comments: [] },
    }).as('getEmptyComments');

    cy.visit('/recipes/101/comments');
    cy.wait('@getEmptyComments');

    cy.contains('No new comments found for this recipe.').should('be.visible');
  });
});

describe('Admin Recipe Comments Moderation - Reply Flow', () => {
  const topLevelComment = {
    id: 'c-1',
    recipe_id: '101',
    parent_id: null,
    author: 'FoodieSam',
    email: 'foodie@example.com',
    content: 'Can I bake this at 375 degrees instead?',
    is_admin: false,
    status: 'approved',
    created_at: '2026-11-18T09:00:00.000Z',
    is_new: true,
  };

  beforeEach(() => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'delisha',
          email: 'delisha@example.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'member',
        status: 'active',
        tenant: {
          id: 't-1',
          name: "Delisha's Kitchen",
          slug: 'delisha-kitchen',
        },
        isImpersonating: false,
      },
    }).as('getMemberSession');

    cy.intercept('GET', '**/api/recipes/101/comments', {
      statusCode: 200,
      body: { comments: [topLevelComment] },
    }).as('getComments');
  });

  it('click Reply button → opens reply form and allows cancellation', () => {
    cy.visit('/recipes/101/comments');
    cy.wait('@getComments');

    // Click Reply
    cy.contains('button', 'Reply').click();

    // Reply form should be displayed
    cy.get('app-recipe-reply-form').should('be.visible');
    cy.get('textarea').should('be.visible');
    cy.contains('button', 'Send').should('be.disabled');

    // Cancel reply
    cy.contains('button', 'Cancel').click();
    cy.get('app-recipe-reply-form').should('not.exist');
    cy.contains('button', 'Reply').should('be.visible');
  });

  it('submit reply → posts reply to API and displays confirmation snackbar', () => {
    const newReply = {
      id: 'r-2',
      recipe_id: '101',
      parent_id: 'c-1',
      author: 'Delisha Marie',
      email: 'delisha@example.com',
      content: 'Yes, 375 works, just add 5 extra minutes.',
      is_admin: true,
      status: 'approved',
      created_at: '2026-11-18T11:00:00.000Z',
      is_new: false,
    };

    cy.intercept('POST', '**/api/recipes/101/comments/c-1/reply', {
      statusCode: 201,
      body: newReply,
    }).as('postReply');

    cy.visit('/recipes/101/comments');
    cy.wait('@getComments');

    cy.contains('button', 'Reply').click();
    cy.get('textarea').type('Yes, 375 works, just add 5 extra minutes.');
    cy.contains('button', 'Send').should('not.be.disabled').click();

    cy.wait('@postReply')
      .its('request.body.content')
      .should('eq', 'Yes, 375 works, just add 5 extra minutes.');

    // Snackbar notification appears
    cy.contains('The message has been sent').should('be.visible');
  });
});

describe('Admin Recipe Comments Moderation - Skip Flow', () => {
  const skippableComment = {
    id: 'c-1',
    recipe_id: '101',
    parent_id: null,
    author: 'SpammyBot',
    email: 'spam@bot.com',
    content: 'Check out cheap watches at example dot com',
    is_admin: false,
    status: 'approved',
    created_at: '2026-11-18T09:00:00.000Z',
    is_new: true,
  };

  beforeEach(() => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'delisha',
          email: 'delisha@example.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'member',
        status: 'active',
        tenant: {
          id: 't-1',
          name: "Delisha's Kitchen",
          slug: 'delisha-kitchen',
        },
        isImpersonating: false,
      },
    }).as('getMemberSession');
  });

  it('click Skip button on comment → marks comment as skipped via API and displays notice', () => {
    cy.intercept('GET', '**/api/recipes/101/comments', {
      statusCode: 200,
      body: { comments: [skippableComment] },
    }).as('getComments');

    cy.intercept('PATCH', '**/api/recipes/101/comments/c-1/skip', {
      statusCode: 200,
      body: { ...skippableComment, status: 'skipped' },
    }).as('patchSkip');

    cy.visit('/recipes/101/comments');
    cy.wait('@getComments');

    cy.contains('button', 'Skip').click();
    cy.wait('@patchSkip');

    cy.contains('This comment was skipped').should('be.visible');
  });
});

